// src/components/Sidebar.jsx
import { Link } from "react-router-dom";

const Sidebar = () => {
  return (
    <div style={{ width: "220px", background: "#1f2937", color: "#fff", padding: "1rem" }}>
      <h2>Rentinel</h2>
      <ul style={{ listStyle: "none", padding: 0 }}>
        <li><Link to="/dashboard" style={{ color: "#fff" }}>Dashboard</Link></li>
        <li><Link to="/properties" style={{ color: "#fff" }}>Properties</Link></li>
        <li><Link to="/tenants" style={{ color: "#fff" }}>Tenants</Link></li>
        <li><Link to="/payments" style={{ color: "#fff" }}>Payments</Link></li>
      </ul>
    </div>
  );
};

export default Sidebar;
